// The limiter and FM soft clip have divisors in [16384, 2097152].
// Normalize, refine a Q29 reciprocal twice, and round it down conservatively.
// Its quotient is at most one low; one exact remainder correction restores it.
static inline uint32_t divide_audio(uint32_t numerator, uint32_t divisor) {
    uint32_t normalized=divisor;unsigned shift=0;
    if(normalized<65536u){normalized<<=16;shift+=16;}
    if(normalized<16777216u){normalized<<=8;shift+=8;}
    if(normalized<268435456u){normalized<<=4;shift+=4;}
    if(normalized<1073741824u){normalized<<=2;shift+=2;}
    if(normalized<2147483648u){normalized<<=1;++shift;}
    normalized>>=1;--shift;
    int32_t reciprocal=division_seed[(normalized>>22)-256];
    for(unsigned iteration=0;iteration<2;++iteration) {
        const int32_t error=536870912-opxy::q31::multiply(static_cast<int32_t>(normalized),reciprocal);
        reciprocal+=4*opxy::q31::multiply(reciprocal,error);
    }
    reciprocal-=16;
    const uint32_t high=static_cast<uint32_t>(opxy::q31::half(opxy::q31::multiply(static_cast<int32_t>(numerator),reciprocal)))
        + (numerator&0x80000000u?static_cast<uint32_t>(reciprocal):0u);
    const uint32_t quotient=high>>(28-shift);
    return quotient+(numerator-quotient*divisor>=divisor?1u:0u);
}
